// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListBuyRequests Browse buy requests
	// (GET /buy-requests)
	ListBuyRequests(ctx context.Context, request ListBuyRequestsRequestObject) (ListBuyRequestsResponseObject, error)
	// CreateBuyRequest Publish a buy request
	// (POST /buy-requests)
	CreateBuyRequest(ctx context.Context, request CreateBuyRequestRequestObject) (CreateBuyRequestResponseObject, error)
	// WithdrawBuyRequest Withdraw an open buy request
	// (DELETE /buy-requests/{buyRequestId})
	WithdrawBuyRequest(ctx context.Context, request WithdrawBuyRequestRequestObject) (WithdrawBuyRequestResponseObject, error)
	// GetBuyRequest Get a buy request
	// (GET /buy-requests/{buyRequestId})
	GetBuyRequest(ctx context.Context, request GetBuyRequestRequestObject) (GetBuyRequestResponseObject, error)
	// AcceptBuyRequest Accept a buy request at its maximum price
	// (POST /buy-requests/{buyRequestId}/accept)
	AcceptBuyRequest(ctx context.Context, request AcceptBuyRequestRequestObject) (AcceptBuyRequestResponseObject, error)
	// Login Create a session
	// (POST /login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// ListMatches List the current user's matches
	// (GET /matches)
	ListMatches(ctx context.Context, request ListMatchesRequestObject) (ListMatchesResponseObject, error)
	// ConfirmMatch Confirm an automatic match
	// (POST /matches/{matchId}/confirm)
	ConfirmMatch(ctx context.Context, request ConfirmMatchRequestObject) (ConfirmMatchResponseObject, error)
	// DeclineMatch Decline an automatic match and release its listings
	// (POST /matches/{matchId}/decline)
	DeclineMatch(ctx context.Context, request DeclineMatchRequestObject) (DeclineMatchResponseObject, error)
	// ListOrders List the current user's orders
	// (GET /orders)
	ListOrders(ctx context.Context, request ListOrdersRequestObject) (ListOrdersResponseObject, error)
	// ConfirmOrderCompletion Confirm an in-person delivery
	// (POST /orders/{orderId}/confirm-completion)
	ConfirmOrderCompletion(ctx context.Context, request ConfirmOrderCompletionRequestObject) (ConfirmOrderCompletionResponseObject, error)
	// ListSellListings Browse sale listings
	// (GET /sell-listings)
	ListSellListings(ctx context.Context, request ListSellListingsRequestObject) (ListSellListingsResponseObject, error)
	// CreateSellListing Publish a sale listing
	// (POST /sell-listings)
	CreateSellListing(ctx context.Context, request CreateSellListingRequestObject) (CreateSellListingResponseObject, error)
	// WithdrawSellListing Withdraw an open sale listing
	// (DELETE /sell-listings/{sellListingId})
	WithdrawSellListing(ctx context.Context, request WithdrawSellListingRequestObject) (WithdrawSellListingResponseObject, error)
	// GetSellListing Get a sale listing
	// (GET /sell-listings/{sellListingId})
	GetSellListing(ctx context.Context, request GetSellListingRequestObject) (GetSellListingResponseObject, error)
	// PurchaseSellListing Buy a sale listing at its listed price
	// (POST /sell-listings/{sellListingId}/purchase)
	PurchaseSellListing(ctx context.Context, request PurchaseSellListingRequestObject) (PurchaseSellListingResponseObject, error)
	// Logout Delete the current session
	// (DELETE /sessions/current)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetCurrentSession Restore the current session
	// (GET /sessions/current)
	GetCurrentSession(ctx context.Context, request GetCurrentSessionRequestObject) (GetCurrentSessionResponseObject, error)
	// Signup Register a user and create a session
	// (POST /signup)
	Signup(ctx context.Context, request SignupRequestObject) (SignupResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

